---
const rows = [
  { id: 1, name: "Notebook", category: "Paper", stock: 14 },
  { id: 2, name: "Fountain pen", category: "Writing", stock: 3 },
  { id: 3, name: "Desk lamp", category: "Lighting", stock: 0 },
];
---

<DataTable
  label="Inventory"
  rows={rows}
  columns={["name", "category", { field: "stock", headerName: "In stock", type: "number" }]}
/>

---
const rows = [
  { id: "A-1001", customer: "Ada Byron", total: 128.5, paid: true, status: "Shipped" },
  { id: "A-1002", customer: "Grace Hopper", total: 42, paid: false, status: "Pending" },
  { id: "A-1003", customer: "Alan Kay", total: null, paid: false, status: "Cancelled" },
];
const statusColor: Record<string, "success" | "warning" | "error"> = {
  Shipped: "success",
  Pending: "warning",
  Cancelled: "error",
};
const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
---

<DataTable
  label="Orders"
  rows={rows}
  columns={[
    { field: "id", headerName: "Order" },
    { field: "customer", headerName: "Customer" },
    {
      field: "total",
      headerName: "Total",
      type: "number",
      valueFormatter: (value) => (value == null ? "None" : money.format(Number(value))),
    },
    { field: "paid", headerName: "Paid", valueFormatter: (value) => (value ? "Yes" : "No") },
    {
      field: "status",
      headerName: "Status",
      renderCell: (params) => (
        <Chip
          size="small"
          label={params.formattedValue}
          color={statusColor[params.formattedValue]}
        />
      ),
    },
  ]}
/>

---
const names = [
  "Atlas",
  "Birch",
  "Cedar",
  "Delta",
  "Ember",
  "Fjord",
  "Grove",
  "Harbor",
  "Inlet",
  "Juniper",
  "Kestrel",
  "Lagoon",
];
const regions = ["North", "Coast", "Valley"];
const rows = names.map((name, index) => ({
  id: index + 1,
  name,
  region: regions[index % 3],
  visits: (index * 37) % 100,
}));
---

<DataTable
  id="sites"
  label="Sites"
  rows={rows}
  columns={[
    { field: "name", headerName: "Site" },
    { field: "region", headerName: "Region" },
    { field: "visits", headerName: "Visits", type: "number" },
  ]}
  quickFilter
  pagination
  paginationModel={{ page: 0, pageSize: 5 }}
  sortModel={[{ field: "visits", sort: "desc" }]}
/>
<p id="sites-state" aria-live="polite"></p>

<script>
  const table = document.getElementById("sites")!;
  const state = document.getElementById("sites-state")!;
  table.addEventListener("clay-pagination-model-change", (event) => {
    state.textContent = `Page ${event.detail.paginationModel.page + 1}`;
  });
  table.addEventListener("clay-sort-model-change", (event) => {
    const [sort] = event.detail.sortModel;
    state.textContent = sort ? `Sorted by ${sort.field}, ${sort.sort}` : "Unsorted";
  });
</script>

---
const rows = [
  {
    id: 1,
    title: "Tide tables",
    author: "M. Reyes",
    summary: "How the moon sets the rhythm of the coast.",
  },
  {
    id: 2,
    title: "Reef survey",
    author: "K. Osei",
    summary: "A season of counts along the outer reef.",
  },
  {
    id: 3,
    title: "Kelp forests",
    author: "L. Park",
    summary: "Why kelp grows fastest in cold water.",
  },
];
---

<DataTable
  id="articles"
  label="Articles"
  rows={rows}
  columns={[
    { field: "title", headerName: "Title" },
    { field: "author", headerName: "Author" },
  ]}
  clickableRows
/>
<Dialog id="article" title="Article" dismissible>
  <p data-article-summary></p>
  <Button slot="actions" variant="text" commandfor="article" command="close">
    Close
  </Button>
  <Button slot="actions" commandfor="article" command="close">
    Read article
  </Button>
</Dialog>
<script type="application/json" id="articles-data" set:html={JSON.stringify(rows)} />
<script>
  type Article = { title: string; summary: string };
  const articles: Article[] = JSON.parse(document.getElementById("articles-data")!.textContent!);
  const dialog = document.getElementById("article") as HTMLDialogElement;
  document.getElementById("articles")!.addEventListener("clay-row-click", (event) => {
    const article = articles[event.detail.rowIndex]!;
    dialog.querySelector(".clay-dialog__title")!.textContent = article.title;
    dialog.querySelector("[data-article-summary]")!.textContent = article.summary;
    dialog.showModal();
  });
</script>

---
const rows = [
  { id: "f1", name: "budget.xlsx", owner: "Ada", size: 24 },
  { id: "f2", name: "logo.svg", owner: "Grace", size: 8 },
  { id: "f3", name: "notes.md", owner: "Alan", size: 2 },
];
---

<DataTable
  id="files"
  label="Files"
  rows={rows}
  columns={[
    { field: "name", headerName: "Name" },
    { field: "owner", headerName: "Owner" },
    { field: "size", headerName: "Size (KB)", type: "number" },
  ]}
  checkboxSelection
>
  <Button slot="toolbar" id="delete-files" variant="outlined" color="error" disabled>
    Delete selected
  </Button>
</DataTable>
<output id="files-request"></output>

<script>
  const remove = document.getElementById("delete-files") as HTMLButtonElement;
  let selected: string[] = [];
  document.getElementById("files")!.addEventListener("clay-row-selection-model-change", (event) => {
    selected = event.detail.rowSelectionModel;
    remove.disabled = selected.length === 0;
  });
  // Rows come from the server: send the ids to your API, then reload the page.
  remove.addEventListener("click", () => {
    document.getElementById("files-request")!.textContent = `DELETE /api/files?ids=${selected}`;
  });
</script>

---
const rows = [
  { id: 1, name: "Ada Byron", email: "ada@example.com" },
  { id: 2, name: "Grace Hopper", email: "grace@example.com" },
];
---

<DataTable
  id="contacts"
  label="Contacts"
  rows={rows}
  columns={[
    { field: "name", headerName: "Name" },
    { field: "email", headerName: "Email" },
    {
      field: "edit",
      type: "actions",
      renderCell: (params) => (
        <IconButton size="small" aria-label={`Edit ${params.row.name}`} data-edit={params.id}>
          <svg
            aria-hidden="true"
            width="18"
            height="18"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
          >
            <path d="M4 20h4L19 9l-4-4L4 16v4Z" />
          </svg>
        </IconButton>
      ),
    },
  ]}
/>
<Dialog id="edit-contact" title="Edit contact">
  <form id="contact-form" method="dialog" class="contact-form">
    <TextField label="Name" name="name" fullWidth />
    <TextField label="Email" name="email" type="email" fullWidth />
  </form>
  <Button slot="actions" variant="text" commandfor="edit-contact" command="close">
    Cancel
  </Button>
  <Button slot="actions" type="submit" form="contact-form">
    Save
  </Button>
</Dialog>

<style>
  .contact-form {
    display: grid;
    gap: 16px;
    padding-block-start: 8px;
  }
</style>

<script>
  import { DIALOG_REQUEST_CLOSE_EVENT } from "@claymo/core/behavior/dialog";

  const dialog = document.getElementById("edit-contact") as HTMLDialogElement;
  const form = document.getElementById("contact-form") as HTMLFormElement;
  const fields = ["name", "email"] as const;
  let row: HTMLTableRowElement | undefined;
  const input = (field: string) => form.elements.namedItem(field) as HTMLInputElement;
  const cell = (field: string) => row!.querySelector(`[data-field="${field}"]`)!;
  const dirty = () => fields.some((field) => input(field).value !== cell(field).textContent);

  document.getElementById("contacts")!.addEventListener("click", (event) => {
    const button = (event.target as Element).closest<HTMLElement>("[data-edit]");
    if (!button) return;
    row = button.closest("tr")!;
    for (const field of fields) input(field).value = cell(field).textContent ?? "";
    dialog.showModal();
  });
  // Save: method="dialog" closes the dialog after submit.
  form.addEventListener("submit", () => {
    for (const field of fields) cell(field).textContent = input(field).value;
  });
  // Escape and backdrop clicks ask first when there are unsaved edits.
  dialog.addEventListener(DIALOG_REQUEST_CLOSE_EVENT, (event) => {
    if (dirty() && !confirm("Discard unsaved changes?")) event.preventDefault();
  });
</script>
